// Builds stable selectors for an element, best first.
// Every candidate is verified: running it on the page must resolve to the same element
// that FastBlaze's {click} would pick (first *visible* match).
(function () {
  'use strict';
  const FB = (globalThis.FastBlaze = globalThis.FastBlaze || {});

  const TEST_ATTRS = ['data-testid', 'data-test-id', 'data-test', 'data-cy', 'data-qa'];
  const LABEL_ATTRS = ['name', 'aria-label', 'placeholder', 'title', 'alt'];
  // Ids generated by frameworks change between renders/builds.
  const AUTO_ID = /^(:r|:R|radix-|headlessui-|react-|mui-|ember\d|ext-gen|rc_|downshift-)|\d{4,}|^[a-f0-9-]{16,}$/i;
  // Utility classes (Tailwind etc.) that are likely to change.
  const FRAGILE_CLASS = /[:[\]/]|^(p|m|px|py|pt|pb|pl|pr|mx|my|mt|mb|ml|mr|w|h|min|max|text|bg|border|rounded|flex|grid|gap|items|justify|font|leading|tracking|shadow|ring|outline|focus|hover|z|top|left|right|bottom|overflow|opacity|transition|duration|ease|cursor|select|space|divide|col|row|order|inline|block|hidden|absolute|relative|fixed|sticky)(-|$)/;

  const cssString = (v) => `"${String(v).replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`;
  const normText = (s) => (s || '').replace(/\s+/g, ' ').trim();

  function testAttr(el) {
    for (const a of TEST_ATTRS) {
      const v = el.getAttribute(a);
      if (v) return `[${a}=${cssString(v)}]`;
    }
    return null;
  }

  function stableId(el) {
    return el.id && !AUTO_ID.test(el.id) ? `#${CSS.escape(el.id)}` : null;
  }

  const anchorOf = (el) => testAttr(el) || stableId(el);

  function resolves(sel, el) {
    try { return FB.dom.findElement(sel) === el; } catch { return false; }
  }

  function countMatches(sel) {
    try { return document.querySelectorAll(sel).length; } catch { return 0; }
  }

  // tag, plus :nth-of-type when siblings share the tag.
  function segment(el) {
    const tag = el.tagName.toLowerCase();
    const parent = el.parentElement;
    if (!parent) return tag;
    const same = [...parent.children].filter((c) => c.tagName === el.tagName);
    return same.length > 1 ? `${tag}:nth-of-type(${same.indexOf(el) + 1})` : tag;
  }

  function stableClasses(el) {
    return [...el.classList].filter((c) => !FRAGILE_CLASS.test(c)).slice(0, 2).map((c) => `.${CSS.escape(c)}`).join('');
  }

  // Walk up until the path is unique, anchoring on test-id / id ancestors when found.
  function pathSelector(el) {
    const parts = [];
    for (let node = el; node && node.nodeType === 1 && node !== document.documentElement; node = node.parentElement) {
      const anchor = node !== el ? anchorOf(node) : null;
      parts.unshift(anchor || segment(node));
      const sel = parts.join(' > ');
      if (resolves(sel, el)) return sel;
      if (anchor) {
        // Anchor found but path not unique: try descendant combinator from the anchor.
        const loose = `${anchor} ${parts.slice(1).join(' > ')}`;
        if (parts.length > 1 && resolves(loose, el)) return loose;
      }
    }
    return parts.join(' > ');
  }

  /**
   * Returns [{ selector?, text?, kind, stability: 'stable'|'ok'|'fragile', count }]
   * stable  = test id / id / name / label attribute
   * ok      = anchored to a stable ancestor, or matched by visible text
   * fragile = structural path / utility classes
   */
  function candidates(el) {
    const out = [];
    const tag = el.tagName.toLowerCase();
    const add = (selector, kind, stability) => {
      if (!selector || out.some((c) => c.selector === selector && c.text == null)) return;
      if (resolves(selector, el)) out.push({ selector, kind, stability, count: countMatches(selector) });
    };

    const t = testAttr(el);
    if (t) add(t, 'test id', 'stable');
    const id = stableId(el);
    if (id) add(id, 'id', 'stable');
    for (const attr of LABEL_ATTRS) {
      const v = el.getAttribute(attr);
      if (v && v.length <= 60) add(`${tag}[${attr}=${cssString(v)}]`, attr, 'stable');
    }
    if ((el.type === 'radio' || el.type === 'checkbox') && el.name && el.value) {
      add(`input[name=${cssString(el.name)}][value=${cssString(el.value)}]`, 'name + value', 'stable');
    }

    // Visible text (great for dropdown options / buttons without test ids).
    const text = normText(el.textContent);
    if (text && text.length <= 40 && !['INPUT', 'TEXTAREA', 'SELECT'].includes(el.tagName)) {
      const found = FB.dom.findByText(text);
      if (found && el.contains(found)) out.push({ text, kind: 'text', stability: 'ok', count: 1 });
    }

    // Anchored to nearest stable ancestor.
    for (let p = el.parentElement, depth = 1; p && depth <= 6; p = p.parentElement, depth++) {
      const a = anchorOf(p);
      if (!a) continue;
      add(`${a} ${tag}`, 'inside ' + a, 'ok');
      add(`${a} ${segment(el)}`, 'inside ' + a, 'ok');
      break;
    }

    const cls = stableClasses(el);
    if (cls) add(`${tag}${cls}`, 'class', 'fragile');
    add(pathSelector(el), 'path', 'fragile');

    const rank = { stable: 0, ok: 1, fragile: 2 };
    return out.sort((a, b) => rank[a.stability] - rank[b.stability]);
  }

  // Escape for use inside a FastBlaze template argument.
  const tplArg = (s) => String(s).replace(/[\\{};]/g, '\\$&');

  /** Template command for a candidate: {click}, or {select} for native selects. */
  function toCommand(c, el) {
    if (el && el.tagName === 'SELECT' && c.selector) {
      const opt = el.selectedOptions[0];
      return `{select: selector=${tplArg(c.selector)}; text=${tplArg(opt ? normText(opt.text) : '')}}`;
    }
    if (c.text != null) return `{click: text=${tplArg(c.text)}}`;
    return `{click: selector=${tplArg(c.selector)}}`;
  }

  FB.selector = { candidates, toCommand, pathSelector, tplArg };
})();
